import numpy as np, os, re, itertools
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp=np.array(G['Demo pair 5 input']); out=np.array(G['Demo pair 5 output'])
bands=[inp[i*3:(i+1)*3] for i in range(4)]
hits=[]
for shifts in itertools.product(range(6),repeat=4):  # horizontal shifts on columns too
    canvas=np.zeros((3,6),int)
    for k,s in zip(range(4),shifts):
        for i in range(3):
            for j in range(6):
                canvas[i,(j+s)%6]=int(bands[k][i,j])
    if list(map(list,canvas))==out.tolist(): hits.append(shifts)
print(hits)

